exe=str(pathlib.Path.cwd()/'executable')
def run(term, columns, color='no'):
    env=os.environ.copy()
    env['BR_INSTALL']='no'
    if term is None:
        env.pop('TERM',None)
    else:
        env['TERM']=term
    if columns is None:
        env.pop('COLUMNS',None)
    else:
        env['COLUMNS']=str(columns)
    r=subprocess.run([exe,'--color',color,'--help'], env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
