    clean=ansi.sub(b'', r.stdout).decode(errors='ignore')
    # get first table border line
    for line in clean.splitlines():
        if line.startswith('┌'):
            border=line
            break
    else:
        border='NO BORDER'
    print(f"TERM={term or 'None'} COLUMNS={columns} -> border len {len(border)} border={border[:80]} total stdout len {len(r.stdout)}")
