REFUSED_CONTENT = b"\\nThis file tells broot you refused the installation of the companion shell function.\\nIf you want to install it run\\n    broot -- install\\n"

# For help width logic
def parse_columns(s):
    if s is None:
        return None
    t = s.lstrip()
    if t == "":
        return None
    if t.startswith('+'):
        t = t[1:]
        if t == "":
            return None
    if t.startswith('-'):
        return None
    if t.lower().startswith('0x'):
        hex_part = t[2:]
        if hex_part == "":
            return None
        if not all(c in "0123456789abcdefABCDEF" for c in hex_part):
            return None
        try:
            val = int(hex_part, 16)
        except:
            return None
        if val <= 0:
            return None
        return val
    if t.startswith('0') and len(t) > 1:
        if not all(c in "01234567" for c in t):
            return None
        try:
            val = int(t, 8)
        except:
            return None
        if val <= 0:
            return None
        return val
    if not t.isdigit():
        return None
    try:
        val = int(t, 10)
    except:
        return None
    if val <= 0:
