    cols_str = os.getenv('COLUMNS')
    if cols_str is None or cols_str == "":
        return 80
    parsed = parse_columns(cols_str)
    if parsed is None:
        return 80
    if parsed > 110:
        return 110
    return parsed

def get_help_bytes():
    w = get_help_width()
    # For w>110 use 110, already capped
    # For width 0? Our parse returns None for 0 => fallback 80, so w never 0 here except for default case 50
    # But we have widths for 0..200
