def error_missing_value(flag, value_name, possible=None):
    if flag in ("--color","--set-install-state"):
        return f"error: a value is required for '{flag} <{value_name}>' but none was supplied\\n  [possible values: {', '.join(possible)}]\\n"
    else:
        return f"error: a value is required for '{flag} <{value_name}>' but none was supplied\\n"

def error_invalid_value(flag, value, value_name, possible=None):
    if flag in ("--color","--set-install-state"):
        # possible values
        msg = f"error: invalid value '{value}' for '{flag} <{value_name}>'\\n  [possible values: {', '.join(possible)}]\\n"
        # check similar tip
        for pv in possible:
            if value.startswith(pv) and value != pv:
                msg = msg.rstrip('\\n') + f"\\n\\n  tip: a similar value exists: '{pv}'\\n"
                break
        return msg
    else:
        if value == "":
            return f"error: invalid value '' for '{flag} <{value_name}>': cannot parse integer from empty string\\n"
        else:
            return f"error: invalid value '{value}' for '{flag} <{value_name}>': invalid digit found in string\\n"

def build_usage_generic():
    return "Usage: executable [OPTIONS] [ROOT]\\n"

def build_usage_with_flags(flag_list, root_present, root_is_flag_unexpected=True):
    # flag_list: list of (long_name, has_value, value_name) for successfully parsed flags
    # root_present: bool
    # root_is_flag_unexpected: if unexpected arg is flag, we show <ROOT> when root present else [ROOT] with flags
    # For generic multiple-times error, original shows "[OPTIONS] [ROOT]" regardless
    # We'll produce generic for multiple-times case outside
    parts = ["executable"]
    for ln, hv, vn in flag_list:
        if ln == "ROOT":
            continue
        if hv:
            parts.append(f"--{ln} <{vn}>")
        else:
            parts.append(f"--{ln}")
    if len(parts) == 1:
        if root_present:
            # When no flags and root present and unexpected is flag, original showed "<ROOT>" (not "[OPTIONS] <ROOT>")
            # For second root (positional), it showed "[OPTIONS] [ROOT]"
            # We will distinguish based on root_is_flag_unexpected
            if root_is_flag_unexpected:
                return "Usage: executable <ROOT>\\n"
            else:
                return "Usage: executable [OPTIONS] [ROOT]\\n"
        else:
            return "Usage: executable [OPTIONS] [ROOT]\\n"
    else:
        # flags present
        if root_present:
            if root_is_flag_unexpected:
                return "Usage: " + " ".join(parts) + " <ROOT>\\n"
            else:
                return "Usage: " + " ".join(parts) + " [ROOT]\\n"
        else:
            return "Usage: " + " ".join(parts) + " [ROOT]\\n"

