        for p in paths:
            if p == "":
                sys.stderr.write("IO Error : No such file or directory (os error 2)\\n")
                sys.exit(1)
            pp = pathlib.Path(p)
            if not pp.exists():
                sys.stderr.write("IO Error : No such file or directory (os error 2)\\n")
                sys.exit(1)
            if pp.is_dir():
