        bash_data.parent.mkdir(parents=True, exist_ok=True)
        bash_data.write_bytes(SHELL_INST.get("bash"))

        output += f"Writing {col_br()} shell function in {col_path(bash_data)}.\\n"

        if had_bash_link:
