            sys.stdout.write(msg)

    # Check bad conf
    default_conf_path = config_dir / "conf.hjson"
    if default_conf_path.exists():
        try:
            txt = default_conf_path.read_text()
            stripped = txt.strip()
            if stripped != "" and not stripped.startswith("#") and stripped != "{}":
                # Heuristic for invalid
                # For cases we have: "old" => Eof at 1:4, "{" => 1:2, "}" => TrailingCharacters, "{invalid}" => ExpectedMapColon
                if stripped == "}":
