def parse_columns(s):
    if s is None:
        return None
    t = s.lstrip()
    if t == "":
        return None
    if t.startswith('+'):
        t = t[1:]
        if t == "":
            return None
    if t.startswith('-'):
        return None
    if t.lower().startswith('0x'):
        hex_part = t[2:]
        if hex_part == "":
            return None
        if not all(c in "0123456789abcdefABCDEF" for c in hex_part):
            return None
        try:
            val = int(hex_part, 16)
        except:
            return None
        if val <= 0:
            return None
        return val
    if t.startswith('0') and len(t) > 1:
        if not all(c in "01234567" for c in t):
            return None
        try:
            val = int(t, 8)
        except:
            return None
        if val <= 0:
            return None
        return val
    if not t.isdigit():
        return None
    try:
        val = int(t, 10)
    except:
        return None
    if val <= 0:
        return None
    return val

def term_exists(term):
    if term is None or term == "":
        return False
    first = term[0] if len(term)>0 else ""
    for base in ["/lib/terminfo", "/usr/share/terminfo"]:
        p = pathlib.Path(base) / first / term
        if p.is_file():
            return True
    return False

def get_help_width():
    term = os.getenv('TERM')
    if term is None or term == "":
        return 50
    if not term_exists(term):
        return 50
    cols_str = os.getenv('COLUMNS')
    if cols_str is None or cols_str == "":
        return 80
    parsed = parse_columns(cols_str)
    if parsed is None:
        return 80
    if parsed > 110:
        return 110
    return parsed

def get_help_bytes():
    w = get_help_width()
    if w in WIDTHS:
        return WIDTHS[w]
    if w > 110 and 110 in WIDTHS:
        return WIDTHS[110]
    if 80 in WIDTHS:
        return WIDTHS[80]
    return DEFAULT_HELP

