    ("trim-root", "t", False, "trim-root", None),
    ("no-trim-root", "T", False, "no-trim-root", None),
    ("outcmd", None, True, "path", None),
    ("verb-output", None, True, "verb-output", None),
    ("cmd", "c", True, "cmd", None),
    ("color", None, True, "color", ["auto","yes","no"]),
    ("height", None, True, "height", None),
    ("install", None, False, "install", None),
    ("set-install-state", None, True, "state", ["undefined","refused","installed"]),
    ("print-shell-function", None, True, "shell", None),
    ("listen", None, True, "socket", None),
    ("listen-auto", None, False, "listen-auto", None),
    ("get-root", None, False, "get-root", None),
    ("write-default-conf", None, True, "path", None),
    ("send", None, True, "socket", None),
]

long_map = {f[0]: f for f in FLAGS}
short_map = {f[1]: f for f in FLAGS if f[1] is not None}

def error_missing_value(flag, value_name, possible=None):
    if flag in ("--color","--set-install-state"):
        return f"error: a value is required for '{flag} <{value_name}>' but none was supplied\\n  [possible values: {', '.join(possible)}]\\n"
    else:
        return f"error: a value is required for '{flag} <{value_name}>' but none was supplied\\n"

def error_invalid_value(flag, value, value_name, possible=None):
    if flag in ("--color","--set-install-state"):
        msg = f"error: invalid value '{value}' for '{flag} <{value_name}>'\\n  [possible values: {', '.join(possible)}]\\n"
        for pv in possible:
            if value.startswith(pv) and value != pv:
                msg = msg.rstrip('\\n') + f"\\n\\n  tip: a similar value exists: '{pv}'\\n"
                break
        return msg
    else:
        if value == "":
            return f"error: invalid value '' for '{flag} <{value_name}>': cannot parse integer from empty string\\n"
        else:
            return f"error: invalid value '{value}' for '{flag} <{value_name}>': invalid digit found in string\\n"

def build_usage_for_unknown(parsed_before, root_present, is_flag=True):
    flag_parts = []
    for ln, hv, vn in parsed_before:
        if ln == "ROOT":
            continue
        if hv:
            flag_parts.append(f"--{ln} <{vn}>")
        else:
            flag_parts.append(f"--{ln}")
    if len(flag_parts)==0:
        if root_present and is_flag:
            return "Usage: executable <ROOT>\\n"
        else:
            return "Usage: executable [OPTIONS] [ROOT]\\n"
    else:
        if root_present and is_flag:
            return "Usage: executable " + " ".join(flag_parts) + " <ROOT>\\n"
        else:
            return "Usage: executable " + " ".join(flag_parts) + " [ROOT]\\n"

def parse_argv(argv):
    parsed = {}
    parsed_before = []
    seen = set()
    root = None
    i=0
    while i < len(argv):
        arg = argv[i]
        if arg == '--':
            remaining = argv[i+1:]
            if len(remaining)==0:
                return None, "error: a value is required for '[ROOT]' but none was supplied\\n", parsed_before, None, True, False
            if remaining[0] == "":
                return None, "error: a value is required for '[ROOT]' but none was supplied\\n", parsed_before, None, True, False
            if len(remaining)>1:
                root = remaining[0]
                flag_parts = [p for p in parsed_before if p[0]!="ROOT"]
                if len(flag_parts)==0:
                    usage = "Usage: executable [OPTIONS] [ROOT]\\n"
                else:
                    parts=["executable"]
                    for ln,hv,vn in flag_parts:
                        if hv:
                            parts.append(f"--{ln} <{vn}>")
                        else:
                            parts.append(f"--{ln}")
                    usage = "Usage: " + " ".join(parts) + " [ROOT]\\n"
                return None, f"error: unexpected argument '{remaining[1]}' found\\n\\n{usage}", parsed_before, root, False, True
            else:
                root = remaining[0]
                parsed_before.append(("ROOT", False, None))
                break

        if arg.startswith('--'):
            if '=' in arg:
                long_eq, value = arg.split('=',1)
                flag_name = long_eq[2:]
                if flag_name == "":
                    root_present = root is not None
                    usage = build_usage_for_unknown(parsed_before, root_present, True)
                    return None, f"error: unexpected argument '{arg}' found\\n\\n  tip: to pass '{arg}' as a value, use '-- {arg}'\\n\\n{usage}", parsed_before, root, False, True
                if flag_name not in long_map:
                    root_present = root is not None
                    usage = build_usage_for_unknown(parsed_before, root_present, True)
                    return None, f"error: unexpected argument '{arg}' found\\n\\n  tip: to pass '{arg}' as a value, use '-- {arg}'\\n\\n{usage}", parsed_before, root, False, True
                entry = long_map[flag_name]
                long_name, short, takes_value, value_name, possible = entry
                if long_name in seen:
                    return None, f"error: the argument '--{flag_name}' cannot be used multiple times\\n\\nUsage: executable [OPTIONS] [ROOT]\\n", parsed_before, root, True, False
                if not takes_value:
                    seen.add(long_name)
                    parsed[long_name]=True
                    parsed_before.append((long_name, False, None))
                else:
                    if value == "":
                        if flag_name in ("color","set-install-state","outcmd","verb-output","write-default-conf"):
                            return None, error_missing_value(f"--{flag_name}", value_name, possible), parsed_before, root, False, False
                    if flag_name == "color":
                        if value not in possible:
                            return None, error_invalid_value(f"--{flag_name}", value, value_name, possible), parsed_before, root, False, False
                    elif flag_name == "set-install-state":
                        if value not in possible:
                            return None, error_invalid_value(f"--{flag_name}", value, value_name, possible), parsed_before, root, False, False
                    elif flag_name in ("height","max-depth"):
                        try:
                            int(value,10)
                        except:
                            if value == "":
                                return None, f"error: invalid value '' for '--{flag_name} <{value_name}>': cannot parse integer from empty string\\n", parsed_before, root, False, False
                            else:
                                return None, f"error: invalid value '{value}' for '--{flag_name} <{value_name}>': invalid digit found in string\\n", parsed_before, root, False, False
                    seen.add(long_name)
                    parsed[long_name]=value
                    parsed_before.append((long_name, True, value_name))
            else:
                flag_name = arg[2:]
                if flag_name not in long_map:
                    root_present = root is not None
                    usage = build_usage_for_unknown(parsed_before, root_present, True)
                    return None, f"error: unexpected argument '{arg}' found\\n\\n  tip: to pass '{arg}' as a value, use '-- {arg}'\\n\\n{usage}", parsed_before, root, False, True
                entry=long_map[flag_name]
                long_name, short, takes_value, value_name, possible = entry
                if long_name in seen:
                    return None, f"error: the argument '--{flag_name}' cannot be used multiple times\\n\\nUsage: executable [OPTIONS] [ROOT]\\n", parsed_before, root, True, False
                if not takes_value:
                    seen.add(long_name)
                    parsed[long_name]=True
                    parsed_before.append((long_name, False, None))
                else:
                    if i+1 >= len(argv):
                        return None, error_missing_value(f"--{flag_name}", value_name, possible), parsed_before, root, False, False
                    next_arg = argv[i+1]
                    if next_arg.startswith('-') and next_arg != "":
                        if flag_name in ("height","max-depth"):
                            flag_parts = [p for p in parsed_before if p[0]!="ROOT"]
                            if len(flag_parts)==0:
                                usage = "Usage: executable [OPTIONS] [ROOT]\\n"
                            else:
                                parts=["executable"]
                                for ln,hv,vn in flag_parts:
                                    if hv:
                                        parts.append(f"--{ln} <{vn}>")
                                    else:
                                        parts.append(f"--{ln}")
                                usage = "Usage: " + " ".join(parts) + " [ROOT]\\n"
                            return None, f"error: unexpected argument '{next_arg}' found\\n\\n  tip: to pass '{next_arg}' as a value, use '-- {next_arg}'\\n\\n{usage}", parsed_before, root, False, True
                        else:
                            return None, error_missing_value(f"--{flag_name}", value_name, possible), parsed_before, root, False, False
                    if next_arg == "":
                        if flag_name in ("color","set-install-state","outcmd","verb-output","write-default-conf"):
                            return None, error_missing_value(f"--{flag_name}", value_name, possible), parsed_before, root, False, False
                    if flag_name == "color":
                        if next_arg not in possible:
                            return None, error_invalid_value(f"--{flag_name}", next_arg, value_name, possible), parsed_before, root, False, False
                    elif flag_name == "set-install-state":
                        if next_arg not in possible:
                            return None, error_invalid_value(f"--{flag_name}", next_arg, value_name, possible), parsed_before, root, False, False
                    elif flag_name in ("height","max-depth"):
                        try:
                            int(next_arg,10)
                        except:
                            if next_arg == "":
                                return None, f"error: invalid value '' for '--{flag_name} <{value_name}>': cannot parse integer from empty string\\n", parsed_before, root, False, False
                            else:
                                return None, f"error: invalid value '{next_arg}' for '--{flag_name} <{value_name}>': invalid digit found in string\\n", parsed_before, root, False, False
                    seen.add(long_name)
                    parsed[long_name]=next_arg
                    parsed_before.append((long_name, True, value_name))
                    i+=1
            i+=1
            continue

        if arg.startswith('-') and arg != '-':
            chars = arg[1:]
            pos=0
            consumed_next=False
            while pos < len(chars):
                ch = chars[pos]
                if ch not in short_map:
                    flag_parts = [p for p in parsed_before if p[0]!="ROOT"]
                    if len(flag_parts)==0:
                        if root is None:
                            usage = "Usage: executable [OPTIONS] [ROOT]\\n"
                        else:
                            usage = "Usage: executable <ROOT>\\n"
                    else:
                        parts=["executable"]
                        for ln,hv,vn in flag_parts:
                            if hv:
                                parts.append(f"--{ln} <{vn}>")
                            else:
                                parts.append(f"--{ln}")
                        if root is None:
                            usage = "Usage: " + " ".join(parts) + " [ROOT]\\n"
                        else:
                            usage = "Usage: " + " ".join(parts) + " <ROOT>\\n"
                    return None, f"error: unexpected argument '-{ch}' found\\n\\n  tip: to pass '-{ch}' as a value, use '-- -{ch}'\\n\\n{usage}", parsed_before, root, False, True
                entry=short_map[ch]
                long_name, short, takes_value, value_name, possible = entry
                if long_name in seen:
                    return None, f"error: the argument '--{long_name}' cannot be used multiple times\\n\\nUsage: executable [OPTIONS] [ROOT]\\n", parsed_before, root, True, False
                if not takes_value:
                    seen.add(long_name)
                    parsed[long_name]=True
                    parsed_before.append((long_name, False, value_name))
                    pos+=1
                    continue
                else:
                    remainder = chars[pos+1:]
                    if remainder != "":
                        value = remainder
                        seen.add(long_name)
                        parsed[long_name]=value
                        parsed_before.append((long_name, True, value_name))
                        break
                    else:
                        if i+1 >= len(argv):
                            return None, error_missing_value(f"--{long_name}", value_name, possible), parsed_before, root, False, False
                        next_arg = argv[i+1]
                        if next_arg.startswith('-') and next_arg != "":
                            flag_parts = [p for p in parsed_before if p[0]!="ROOT"]
                            if len(flag_parts)==0:
                                usage = "Usage: executable [OPTIONS] [ROOT]\\n"
                            else:
                                parts=["executable"]
                                for ln,hv,vn in flag_parts:
                                    if hv:
                                        parts.append(f"--{ln} <{vn}>")
                                    else:
                                        parts.append(f"--{ln}")
                                usage = "Usage: " + " ".join(parts) + " [ROOT]\\n"
                            return None, f"error: unexpected argument '{next_arg}' found\\n\\n  tip: to pass '{next_arg}' as a value, use '-- {next_arg}'\\n\\n{usage}", parsed_before, root, False, True
                        seen.add(long_name)
                        parsed[long_name]=next_arg
                        parsed_before.append((long_name, True, value_name))
                        consumed_next=True
                        break
            if consumed_next:
                i+=1
            i+=1
            continue

        if root is not None:
            return None, f"error: unexpected argument '{arg}' found\\n\\nUsage: executable [OPTIONS] [ROOT]\\n", parsed_before, root, False, True
        if arg == "":
            return None, "error: a value is required for '[ROOT]' but none was supplied\\n", parsed_before, root, False, False
        root = arg
        parsed_before.append(("ROOT", False, None))
        i+=1

    return parsed, None, parsed_before, root, False, False

def main():
    argv = sys.argv[1:]
    parsed, err_msg, parsed_before, root, is_multiple, is_unknown = parse_argv(argv)

    if err_msg is not None:
        sys.stderr.write(err_msg)
        sys.exit(2)

    HOME = os.getenv('HOME') or str(pathlib.Path.home())
    BROOT_CONFIG_DIR = os.getenv('BROOT_CONFIG_DIR')
    XDG_CONFIG_HOME = os.getenv('XDG_CONFIG_HOME')
    XDG_DATA_HOME = os.getenv('XDG_DATA_HOME')

    if BROOT_CONFIG_DIR:
        config_dir = pathlib.Path(BROOT_CONFIG_DIR)
    elif XDG_CONFIG_HOME:
        config_dir = pathlib.Path(XDG_CONFIG_HOME) / "broot"
    else:
        config_dir = pathlib.Path(HOME) / ".config" / "broot"

    if XDG_DATA_HOME:
        data_dir = pathlib.Path(XDG_DATA_HOME) / "broot" / "launcher"
    else:
        data_dir = pathlib.Path(HOME) / ".local" / "share" / "broot" / "launcher"

    if XDG_CONFIG_HOME:
        fish_base = pathlib.Path(XDG_CONFIG_HOME)
    else:
        fish_base = pathlib.Path(HOME) / ".config"
    fish_dir = fish_base / "fish"
    fish_functions_file = fish_base / "fish" / "functions" / "br.fish"
    fish_data_file = data_dir / "fish" / "br.fish"

    nushell_base = fish_base
    nushell_dir = nushell_base / "nushell"
    nushell_config_file = nushell_dir / "config.nu"
    nushell_data_file = data_dir / "nushell" / "6"
    nushell_link_file = config_dir / "launcher" / "nushell" / "br"

    bash_data_file = data_dir / "bash" / "1"
    bash_link_file = config_dir / "launcher" / "bash" / "br"

    installed_file = config_dir / "launcher" / "installed-v4"
    refused_file = config_dir / "launcher" / "refused"

    has_help = "help" in parsed
    has_version = "version" in parsed
    has_print = "print-shell-function" in parsed
    has_write = "write-default-conf" in parsed
    has_set = "set-install-state" in parsed
    has_install = "install" in parsed
    has_conf = "conf" in parsed

    if has_conf and not (has_help or has_version or has_print or has_write or has_set):
        conf_val = parsed.get("conf") or ""
        paths = conf_val.split(';') if conf_val else [""]
        for p in paths:
            if p == "":
                sys.stderr.write("IO Error : No such file or directory (os error 2)\\n")
                sys.exit(1)
            pp = pathlib.Path(p)
            if not pp.exists():
                sys.stderr.write("IO Error : No such file or directory (os error 2)\\n")
                sys.exit(1)
            if pp.is_dir():
                sys.stderr.write("IO Error : Is a directory (os error 21)\\n")
                sys.exit(1)

    if has_write:
        write_path = parsed.get("write-default-conf")
        wp = pathlib.Path(write_path)
        if wp.exists() and wp.is_file():
            sys.stderr.write(f"IO Error : \\"{write_path}\\" isn't a directory\\n")
            sys.exit(1)
        try:
            wp.mkdir(parents=True, exist_ok=True)
        except:
            sys.stderr.write("IO Error : No such file or directory (os error 2)\\n")
            sys.exit(1)
        conf_dest = wp / "conf.hjson"
        if not conf_dest.exists():
            conf_dest.write_bytes(CONF_HJSON)
        verbs_dest = wp / "verbs.hjson"
        if not verbs_dest.exists():
            verbs_dest.write_bytes(VERBS_HJSON)
        skins_dir = wp / "skins"
        skins_dir.mkdir(parents=True, exist_ok=True)
        for name, data in SKINS.items():
            dest = skins_dir / name
            if not dest.exists():
                dest.write_bytes(data)

    removing_messages = []
    if has_set:
        state = parsed.get("set-install-state")
        launcher_dir = config_dir / "launcher"
        launcher_dir.mkdir(parents=True, exist_ok=True)
        installed_path = launcher_dir / "installed-v4"
        refused_path = launcher_dir / "refused"

        def add_removing(p):
            msg = f"Removing \\x1b[48;5;234m\\x1b[38;5;250m{p}\\x1b[49m\\x1b[39m.\\n"
            removing_messages.append(msg)

        had_refused = refused_path.exists()
        had_installed = installed_path.exists()

        if had_refused:
            try:
                refused_path.unlink()
            except:
                pass
            add_removing(refused_path)
        if had_installed:
            try:
                installed_path.unlink()
            except:
                pass
            add_removing(installed_path)

        if state == "installed":
            installed_path.write_bytes(INSTALLED_CONTENT)
        elif state == "refused":
            refused_path.write_bytes(REFUSED_CONTENT)

    has_print_valid = False
    print_shell_name = None
    if has_print:
        shell_name = parsed.get("print-shell-function")
        print_shell_name = shell_name
        if shell_name in ("bash","zsh","fish","powershell","nushell"):
            has_print_valid = True
        else:
            stdout_bytes = b""
            if has_help:
                stdout_bytes += get_help_bytes()
            if has_version:
                stdout_bytes += VERSION.encode()
            for msg in removing_messages:
                stdout_bytes += msg.encode()
            sys.stdout.buffer.write(stdout_bytes)
            sys.stderr.write(f"Unknown shell: {shell_name}\\n")
            sys.exit(1)

    if has_help or has_version or has_print_valid or has_write or has_set:
        stdout_bytes = b""
        if has_help:
            stdout_bytes += get_help_bytes()
        if has_version:
            stdout_bytes += VERSION.encode()
        if has_set:
            for msg in removing_messages:
                stdout_bytes += msg.encode()
        if has_print_valid:
            if print_shell_name in ("bash","zsh"):
                stdout_bytes += BASH_PRINT
            elif print_shell_name == "fish":
                stdout_bytes += FISH_PRINT
            elif print_shell_name == "powershell":
                stdout_bytes += PS_PRINT
            elif print_shell_name == "nushell":
                stdout_bytes += NU_PRINT
        sys.stdout.buffer.write(stdout_bytes)
        sys.exit(0)

    if has_install:
        output = ""
        output += "You requested a clean (re)install.\\n"

        launcher_dir = config_dir / "launcher"
        launcher_dir.mkdir(parents=True, exist_ok=True)
        installed_path = launcher_dir / "installed-v4"
        refused_path = launcher_dir / "refused"

        def col_path(p):
            return f"\\x1b[48;5;234m\\x1b[38;5;250m{p}\\x1b[49m\\x1b[39m"

        def col_br():
            return f"\\x1b[38;5;13m\\x1b[3mbr\\x1b[0m"

        def add_removing_install(p):
            nonlocal output
            output += f"Removing {col_path(p)}.\\n"

        had_refused = refused_path.exists()
        had_installed = installed_path.exists()

        if had_refused:
            try:
                refused_path.unlink()
            except:
                pass
            add_removing_install(refused_path)
        if had_installed:
            try:
                installed_path.unlink()
            except:
                pass
            add_removing_install(installed_path)

        bash_data = data_dir / "bash" / "1"
        bash_link = config_dir / "launcher" / "bash" / "br"

        had_bash_data = bash_data.exists()
        had_bash_link = bash_link.exists() or bash_link.is_symlink()

        if had_bash_data:
            try:
                bash_data.unlink()
            except:
                pass
            add_removing_install(bash_data)

        bash_data.parent.mkdir(parents=True, exist_ok=True)
        bash_data.write_bytes(SHELL_INST.get("bash"))

        output += f"Writing {col_br()} shell function in {col_path(bash_data)}.\\n"

        if had_bash_link:
            try:
                bash_link.unlink()
            except:
                pass
            add_removing_install(bash_link)

        bash_link.parent.mkdir(parents=True, exist_ok=True)
        try:
            bash_link.symlink_to(bash_data)
        except:
            try:
                bash_link.unlink()
                bash_link.symlink_to(bash_data)
            except:
                pass
        output += f"Creating link from {col_path(bash_link)} to {col_path(bash_data)}.\\n"

        HOME_PATH = pathlib.Path(HOME)
        bashrc_path = HOME_PATH / ".bashrc"
        zshrc_path = HOME_PATH / ".zshrc"

        bashrc_exists = bashrc_path.is_file()
        zshrc_exists = zshrc_path.is_file()
        bashrc_is_dir = bashrc_path.is_dir()
        zshrc_is_dir = zshrc_path.is_dir()

        if bashrc_exists:
            try:
                content = bashrc_path.read_text()
                src_line = f"source {bash_link}"
                if src_line in content:
                    output += f"{col_path(bashrc_path)} already patched, no change made.\\n"
                else:
                    if content.endswith("\\n"):
                        new_content = content + "\\n" + src_line + "\\n"
                    else:
                        new_content = content + "\\n" + src_line + "\\n"
                    bashrc_path.write_text(new_content)
                    output += f"{col_path(bashrc_path)} successfully patched, you can make the function immediately available with \\x1b[48;5;234m\\x1b[38;5;250msource \\x1b[49m\\x1b[39m\\x1b[48;5;234m\\x1b[38;5;250m{bashrc_path}\\x1b[49m\\x1b[39m\\n"
            except IsADirectoryError:
                sys.stderr.write(f"IO Error Is a directory (os error 21) on reading line in \\"{bashrc_path}\\"\\n")
        elif bashrc_is_dir:
            sys.stderr.write(f"IO Error Is a directory (os error 21) on reading line in \\"{bashrc_path}\\"\\n")

        if zshrc_exists:
            try:
                content = zshrc_path.read_text()
                src_line = f"source {bash_link}"
                if src_line in content:
                    output += f"{col_path(zshrc_path)} already patched, no change made.\\n"
                else:
                    if content.endswith("\\n"):
                        new_content = content + "\\n" + src_line + "\\n"
                    else:
                        new_content = content + "\\n" + src_line + "\\n"
                    zshrc_path.write_text(new_content)
                    output += f"{col_path(zshrc_path)} successfully patched, you can make the function immediately available with \\x1b[48;5;234m\\x1b[38;5;250mexec zsh\\x1b[49m\\x1b[39m\\n"
            except IsADirectoryError:
                sys.stderr.write(f"IO Error Is a directory (os error 21) on reading line in \\"{zshrc_path}\\"\\n")
        elif zshrc_is_dir:
            sys.stderr.write(f"IO Error Is a directory (os error 21) on reading line in \\"{zshrc_path}\\"\\n")

        if not bashrc_exists and not zshrc_exists:
            output += "\\nI found no sourcing file for the bash/zsh family.\\nIf you're using bash or zsh, then installation \\nisn't complete:\\nthe br function initialization script won't be \\nsourced unless you source it yourself.\\n"

        # Fish - if fish_dir exists (file or dir)
        if fish_dir.exists():
            f_data = fish_data_file
            f_link = fish_functions_file
            had_f_data = f_data.exists()
            had_f_link = f_link.exists() or f_link.is_symlink()

            if had_f_data:
                try:
                    f_data.unlink()
                except:
                    pass
                add_removing_install(f_data)

            f_data.parent.mkdir(parents=True, exist_ok=True)
            try:
                f_data.write_bytes(SHELL_INST.get("fish"))
