        if fish_dir.is_dir():
            should_final = True
        if nushell_config_file.is_file():
            should_final = True

        if should_final:
            output += "\nThe \x1b[1mbr\x1b[0m function has been successfully installed.\nYou may have to restart your shell or source your \nshell init files.\nAfterwards, you should start broot with \x1b[48;5;234m\x1b[38;5;250mbr\x1b[49m\x1b[39m in \norder to use its full power.\n\n"

        sys.stdout.write(output)
