    # TUI mode simplified
    new_config_created = False
    if not (config_dir / "conf.hjson").exists():
        try:
            config_dir.mkdir(parents=True, exist_ok=True)
        except:
            pass
        conf_dest = config_dir / "conf.hjson"
        if not conf_dest.exists():
            conf_dest.write_bytes(CONF_HJSON)
            new_config_created = True
        verbs_dest = config_dir / "verbs.hjson"
        if not verbs_dest.exists():
            verbs_dest.write_bytes(VERBS_HJSON)
        skins_dir = config_dir / "skins"
        skins_dir.mkdir(parents=True, exist_ok=True)
        for name, data in SKINS.items():
            dest = skins_dir / name
            if not dest.exists():
                dest.write_bytes(data)
        if new_config_created:
            msg = f"New Configuration files written in \x1b[1m\"{config_dir}\"\\x1b[0m.\nYou should have a look at them: their comments will help you configure broot.\nYou should especially set up your favourite editor in verbs.hjson.\n"
            sys.stdout.write(msg)

    default_conf_path = config_dir / "conf.hjson"
    if default_conf_path.exists():
        try:
            txt = default_conf_path.read_text()
            stripped = txt.strip()
            if stripped != "" and not stripped.startswith("#") and stripped != "{}":
                if stripped == "}":
                    sys.stderr.write(f"Bad configuration file \"{default_conf_path}\" : unable to parse Hjson: TrailingCharacters at 1:1 at \"{stripped}\"\n")
                    sys.exit(1)
                elif stripped == "{":
                    sys.stderr.write(f"Bad configuration file \"{default_conf_path}\" : unable to parse Hjson: Eof at 1:2 at ""\n")
                    sys.exit(1)
                elif stripped == "old":
                    sys.stderr.write(f"Bad configuration file \"{default_conf_path}\" : unable to parse Hjson: Eof at 1:4 at ""\n")
                    sys.exit(1)
                elif len(stripped) < 20:
                    sys.stderr.write(f"Bad configuration file \"{default_conf_path}\" : unable to parse Hjson: Eof at 1:{len(stripped)+1} at ""\n")
                    sys.exit(1)
        except IsADirectoryError:
            sys.stderr.write(f"IO Error : Is a directory (os error 21)\n")
            sys.exit(1)
        except SystemExit:
            raise
        except:
            pass

    if root is not None:
        rp = pathlib.Path(root)
        if not rp.exists():
            sys.stderr.write("IO Error : No such file or directory (os error 2)\n")
            sys.exit(1)

    if "send" in parsed:
        send_path = parsed.get("send") or ""
        sp = pathlib.Path(send_path)
        if not sp.exists():
            sys.stderr.write("error on the socket: No such file or directory (os error 2)\n")
            sys.exit(1)

    sys.stderr.write("\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?1006l\\x1b[?1015l\\x1b[?1003l\\x1b[?1002l\\x1b[?1000l\\x1b[?25h\\x1b[?1049lTermimad Error : IO error: No such device or address (os error 6)\\n")
    sys.exit(1)

if __name__ == "__main__":
    main()
